import { useQuery } from "@tanstack/react-query";
import { useEffect, useMemo } from "react";
import { credentialFingerprint, getBotData } from "../api";
import type { Flow, BotData } from "../types";
import { createFlowNodesFromFlowSteps } from "../utils/flow-import";
import { inspectorStore, useInspectorStore } from "../store";
import { setEngineType, setSkillCatalog } from "../store/actions";

export const useConversationData = () => {
  const projectUrl = useInspectorStore((s) => s.projectUrl);
  const botDataEndpoint = useInspectorStore((s) => s.botDataEndpoint);
  const httpAuth = useInspectorStore((s) => s.httpAuth);

  const {
    data: botData,
    isLoading,
    error,
  } = useQuery<BotData, Error>({
    queryKey: [
      "botData",
      projectUrl,
      botDataEndpoint,
      httpAuth?.via,
      credentialFingerprint(httpAuth?.token),
    ],
    queryFn: () => getBotData({ projectUrl, botDataEndpoint, httpAuth }),
    enabled: !!projectUrl,
    refetchOnWindowFocus: false,
  });

  const botFlows = botData?.flows;
  // Absence of the engine field means calm — protocol compatibility with
  // released v1 backends served by the published /lib package.
  const isMantleEngine = botData?.engine === "mantle";

  const flows = useMemo(() => {
    if (!botFlows) return [];
    // Skill-based (Mantle) projects render from the skills catalog; the flows
    // key is a v1 concept and is not consumed in skill mode (the backend
    // serves it empty there anyway). Keyed off the declared engine, not off
    // the presence of the skills catalog.
    if (isMantleEngine) return [];

    const allFlows: Flow[] = [];
    for (const [flowId, flow] of Object.entries(botFlows)) {
      const { nodes: newNodes, edges: newEdges } = createFlowNodesFromFlowSteps(
        flow.steps,
        flowId,
        Object.keys(botFlows),
      );
      allFlows.push({
        id: flowId,
        name: flow.name || flowId,
        description: flow.description,
        nodes: newNodes,
        edges: newEdges,
      });
    }

    return allFlows;
  }, [botFlows, isMantleEngine]);

  useEffect(() => {
    inspectorStore.setState((prev) => ({
      ...prev,
      flows,
      flowsLoading: isLoading,
      flowsError: error,
    }));
  }, [flows, isLoading, error]);

  useEffect(() => {
    if (botData?.assistant_id !== undefined) {
      inspectorStore.setState((prev) => ({
        ...prev,
        assistantId: botData.assistant_id ?? null,
      }));
    }
  }, [botData?.assistant_id]);

  useEffect(() => {
    if (botData) {
      // Absence of the engine field means calm (released v1 backends).
      setEngineType(botData.engine ?? "calm");
      setSkillCatalog(botData.skills ?? null);
    }
  }, [botData]);
};
